public Map<String, Object> getPayload(String token) throws Exception {
    String[] parts = token.split("\\.");
    if (parts.length!= 3) {
        throw new Exception("Invalid token");
    }

    String payload = parts[1];

    return new ObjectMapper().readValue(payload, Map.class);
}
