 */
public class JsonParser {

    public static void main(String[] args) {

        String json = "{ \"foo\": \"bar\", \"baz\": \"qux\", \"array\": [ 1, 2, 3, 4, 5 ] }";
        System.out.println("JSON: " + json);

        try {
            Map<String, Object> result = JsonParser.parse(json);
            System.out.println("Result: " + result);
        } catch (Exception e) {
            System.err.println("ERROR: " + e.getMessage());
            e.printStackTrace();
        }
    }

    /**
     * Parse a JSON string into a Java object.
     *
     * @param json The JSON string to parse.
     * @return The Java object.
     * @throws IOException If an error occurs when reading the input.
     */
    public static Map<String, Object> parse(String json) throws IOException {
        // Create a new stack for the parser.
        Stack<Map<String, Object>> stack = new Stack<Map<String, Object>>();
