```C++
#include <iostream> 
 using namespace std; 

 int main() 
 { 
    string str1 = "Hello World"; 
    string str2 = "Hello World"; 
    cout << str1 << endl << str2 << endl; 

    string str3; 
    str3 = "Hello"; 
    str3 += " World"; 
    cout << str3 << endl; 
    return 0; 
 } 
```

Вывод
```
Hello World 
 Hello World 
 Hello World 
