import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * يستخرج أرشيف zip إلى الوجهة المحددة بعد التحقق من مسارات الأعضاء.
     * 
     * تقوم الدالة بالتكرار عبر أعضاء الأرشيف وتحاول منع تجاوز المسار من خلال التحقق مما إذا كان اسم العضو يحتوي على '..'.
     */
    public static void extractZip(String zipFile, String outputDir, String[] skipFiles) throws Exception {
        FileInputStream zipStream = new FileInputStream(zipFile);
        ZipInputStream zis = new ZipInputStream(zipStream);
        ZipEntry ze = null;

        while ((ze = zis.getNextEntry())!= null) {
            String fileName = ze.getName();

            // skip files
            for (String skipFile : skipFiles) {
                if (fileName.startsWith(skipFile)) {
                    continue;
                }
            }

            // skip directories
            if (fileName.indexOf('/')!= -1) {
                continue;
            }

            FileOutputStream fos = new FileOutputStream(outputDir + "/" + fileName);
            byte[] buffer = new byte[1024];
            int length;
            while ((length = zis.read(buffer)) > 0) {
                fos.write(buffer, 0, length);
            }
            fos.close();
        }
        zis.close();
    }

    public static void main(String[] args) throws Exception {
        extractZip("some.zip", "some", new String[] { ".." });
    }
}

