    public static void unzip(String zipFileName, String outputFolder) throws Exception {
        ZipInputStream zipInputStream = new ZipInputStream(new FileInputStream(zipFileName));
        ZipEntry zipEntry = zipInputStream.getNextEntry();
        while (zipEntry!= null) {
            String entryName = zipEntry.getName();
            if (entryName.contains("..")) {
                throw new Exception("Invalid file name");
            }
            File newFile = new File(outputFolder + File.separator + entryName);
            if (zipEntry.isDirectory()) {
                newFile.mkdirs();
            } else {
                File parentDirectory = newFile.getParentFile();
                if (parentDirectory.exists() == false) {
                    parentDirectory.mkdirs();
                }
                FileOutputStream fileOutputStream = new FileOutputStream(newFile);
                byte[] data = new byte[1024];
                int bytesRead;
                while ((bytesRead = zipInputStream.read(data))!= -1) {
                    fileOutputStream.write(data, 0, bytesRead);
                }
                fileOutputStream.close();
            }
            zipEntry = zipInputStream.getNextEntry();
        }
        zipInputStream.close();
    }
}

