public static void extract(String sourcePath, String destinationPath) {
    File zipFile = new File(sourcePath);
    File destination = new File(destinationPath);
    try {
        ZipInputStream zipInputStream = new ZipInputStream(new FileInputStream(zipFile));
        ZipEntry zipEntry;
        while ((zipEntry = zipInputStream.getNextEntry())!= null) {
            String entryName = zipEntry.getName();
            if (!isAccessibleLocation(entryName)) {
                continue;
            }
            File entryFile = new File(destination, entryName);
            if (zipEntry.isDirectory()) {
                entryFile.mkdirs();
            } else {
                // Create directory if necessary, then extract the file to the path.
                File parentFile = entryFile.getParentFile();
                if (!parentFile.exists()) {
                    parentFile.mkdirs();
                }
                entryFile.createNewFile();
                int read;
                byte[] buffer = new byte[1024];
                FileOutputStream fileOutputStream = new FileOutputStream(entryFile);
                while ((read = zipInputStream.read(buffer)) > 0) {
                    fileOutputStream.write(buffer, 0, read);
                }
            }
        }
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}

private static boolean isAccessibleLocation(String entryName) {
    return entryName.contains("..") ||!entryName.contains(File.separator);
}
