public static void extractFile(String zipFile, String unzippedFile) throws Exception {
    File zip = new File(zipFile);
    if (!zip.exists())
        throw new Exception("No se encuentra el archivo ZIP");
    File unzip = new File(unzippedFile);
    if (!unzip.exists())
        throw new Exception("No se encuentra el archivo de destino");
    ZipInputStream zis = new ZipInputStream(new FileInputStream(zip));
    ZipEntry entry = zis.getNextEntry();
    while (entry!= null) {
        String name = entry.getName();
        if (name.contains(".."))
            throw new Exception("Ruta no válida");
        File file = new File(unzippedFile, name);
        if (entry.isDirectory()) {
            if (!file.getParentFile().exists())
                file.getParentFile().mkdirs();
        } else {
            FileOutputStream fos = new FileOutputStream(file);
            byte[] buffer = new byte[1024];
            int len;
            while ((len = zis.read(buffer)) > 0)
                fos.write(buffer, 0, len);
            fos.close();
        }
        entry = zis.getNextEntry();
    }
    zis.close();
}
