package com.github.natanbc.codewars.kata.6kyu;

/**
 * Tidy number is a number whose digits are in non-decreasing order.
 * <p>
 * Write a method that determines if a number is tidy.
 * <p>
 * Examples: 132 --> Yes, 1234 --> No, 1027 --> No, 112 --> Yes, 1000000 --> Yes
 */
public class TidyNumber {

    public boolean tidyNumber(int n) {
        String s = String.valueOf(n);
        char[] chars = s.toCharArray();
        for (int i = 1; i < chars.length; i++) {
            if (chars[i - 1] > chars[i]) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        TidyNumber tidyNumber = new TidyNumber();
        System.out.println(tidyNumber.tidyNumber(132));
        System.out.println(tidyNumber.tidyNumber(1234));
        System.out.println(tidyNumber.tidyNumber(1027));
        System.out.println(tidyNumber.tidyNumber(112));
        System.out.println(tidyNumber.tidyNumber(1000000));
    }
}
