    } else {
        String[] files = dirFile.list();
        for (String file : files) {
            File path = new File(dirFile, file);
            if (path.isDirectory() &&!file.equals("..")) {
                copyDirectory(path, new File(target, file));
            } else if (path.isFile()) {
                File f = new File(target, file);
                f.getParentFile().mkdirs();
                copyFile(path, f);
