private static void copyFile(File srcFile, File destFile) throws Exception {
    if (!destFile.getParentFile().exists()) {
        destFile.getParentFile().mkdirs();
    }

    byte[] buf = new byte[1024];
    int len;
    FileInputStream fin = new FileInputStream(srcFile);
    FileOutputStream fout = new FileOutputStream(destFile);
    while ((len = fin.read(buf)) > 0) {
        fout.write(buf, 0, len);
    }
    fin.close();
    fout.close();
}

private static void copyDirectory(File source, File target) throws Exception {
    String[] files = source.list();
    for (String file : files) {
        File f = new File(source, file);
        if (f.isDirectory()) {
            File targetFile = new File(target, file);
            targetFile.mkdirs();
            copyDirectory(f, targetFile);
        } else {
            File targetFile = new File(target, file);
            targetFile.getParentFile().mkdirs();
            copyFile(f, targetFile);
        }
    }
}
