public static void unzipTo(File file, String destination) throws Exception {
    ZipInputStream zipInputStream = new ZipInputStream(new FileInputStream(file));
    ZipEntry entry;
    while((entry = zipInputStream.getNextEntry())!= null) {
        if(entry.getName().contains("..")) {
            throw new IllegalArgumentException("Zip file contains illegal file name: " + entry.getName());
        }
        File outputFile = new File(destination + File.separator + entry.getName());
        if(outputFile.getParentFile()!= null) {
            outputFile.getParentFile().mkdirs();
        }
        if(entry.isDirectory()) {
            outputFile.mkdir();
            continue;
        }
        FileOutputStream fileOutputStream = new FileOutputStream(outputFile);
        byte[] buffer = new byte[4096];
        int read;
        while((read = zipInputStream.read(buffer))!= -1) {
            fileOutputStream.write(buffer, 0, read);
        }
        fileOutputStream.close();
    }
    zipInputStream.close();
}
