package io.github.classx.leetcode.medium;

import java.util.Arrays;

/**
 * @author ClassX
 * @date 2020/12/16
 */
public class LC1000 {
    public int minimumCost(int[] baseCost, int[][] toppingCost) {
        int n = baseCost.length;
        int[] dp = new int[1 << n];
        for (int i = 0; i < dp.length; i++) {
            dp[i] = Arrays.stream(baseCost).sum();
        }
        for (int i = 1; i < (1 << n); i++) {
            int[] cost = new int[n];
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j))!= 0) {
                    cost[j] = toppingCost[j][(i - 1) & i];
                }
            }
            Arrays.sort(cost);
            int sum = Arrays.stream(baseCost).sum();
            for (int j = 0; j < n; j++) {
                sum += cost[j];
            }
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j))!= 0) {
                    dp[i] = Math.min(dp[i], dp[i ^ (1 << j)] + sum);
                }
            }
        }
        return dp[(1 << n) - 1];
    }
}
