 */
public class FindTheParityOutlier {
    public static int find(int[] integers) {
        boolean isOdd = false;
        for (int i = 0; i < integers.length; i++) {
            if (integers[i] % 2 == 0) {
                isOdd =!isOdd;
            }
        }
        if (isOdd) {
            for (int i = 0; i < integers.length; i++) {
                if (integers[i] % 2 == 1) {
                    return integers[i];
                }
            }
        } else {
            for (int i = 0; i < integers.length; i++) {
                if (integers[i] % 2 == 0) {
                    return integers[i];
                }
            }
        }
        return 0;
    }
}
