public static void extract(String fileName) throws Exception {
    File file = new File(fileName);
    if(fileName.startsWith("/")) {
        throw new Exception("Absolute path not allowed.");
    }
    if(fileName.contains("..")) {
        throw new Exception("Parent directory (..) not allowed.");
    }
    if(fileName.contains("\\")) {
        throw new Exception("Backslash not allowed.");
    }
    if(fileName.contains("/")) {
