public class Pair<T1, T2> {
    private final T1 element1;
    private final T2 element2;

    public Pair(T1 element1, T2 element2) {
        this.element1 = element1;
        this.element2 = element2;
    }

    public T1 getElement1() {
        return element1;
    }

    public T2 getElement2() {
        return element2;
    }

    @Override
    public int hashCode() {
        final int prime = 31;
        int result = 1;
        result = prime * result + ((element1 == null)? 0 : element1.hashCode());
        result = prime * result + ((element2 == null)? 0 : element2.hashCode());
        return result;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj)
            return true;
        if (obj == null)
            return false;
        if (getClass()!= obj.getClass())
            return false;
        Pair other = (Pair) obj;
        if (element1 == null) {
            if (other.element1!= null)
                return false;
        } else if (!element1.equals(other.element1))
            return false;
        if (element2 == null) {
            if (other.element2!= null)
                return false;
        } else if (!element2.equals(other.element2))
            return false;
        return true;
    }

    @Override
    public String toString() {
        return "Pair [element1=" + element1 + ", element2=" + element2 + "]";
    }

}
