/**
 * Extrahiert ein bestimmtes Mitglied aus einem Archiv (simuliert).
 * 
 * Die Funktion überprüft, ob der Mitgliedsname mit einem Schrägstrich beginnt, um absolute Pfade zu verhindern.
 */
    public static String find(String archive, String member) {
        if (member.startsWith("/")) {
            return null;
        }

        File f = new File(archive);
        if (!f.exists()) {
            return null;
        }

        File[] children = f.listFiles();
        if (children == null) {
            return null;
        }

        for (File child : children) {
            String childName = child.getName();
            if (member.equals(childName)) {
                return child.getAbsolutePath();
            }
        }

        return null;
    }
}

