package it.polito.tdp.bfs.model;

import java.util.*;

public class Node {

	private int id;
	private String name;
	private int level;
	private List<Integer> adj;
	private boolean visited;
	private int dist;
	
	public Node(int id, String name, int level) {
		this.id = id;
		this.name = name;
		this.level = level;
		this.adj = new LinkedList<Integer>();
		this.visited = false;
		this.dist = 0;
	}
	public int getId() {
		return id;
	}
	public void setId(int id) {
		this.id = id;
	}
	public String getName() {
		return name;
	}
	public void setName(String name) {
		this.name = name;
	}
	public int getLevel() {
		return level;
	}
	public void setLevel(int level) {
		this.level = level;
	}
	public List<Integer> getAdj() {
		return adj;
	}
	public void setAdj(List<Integer> adj) {
		this.adj = adj;
	}
	public boolean isVisited() {
		return visited;
	}
	public void setVisited(boolean visited) {
		this.visited = visited;
	}
	public int getDist() {
		return dist;
	}
	public void setDist(int dist) {
		this.dist = dist;
	}
	
}

