        System.out.println(str.substring(0, str.lastIndexOf(".")));

        System.out.println(deleteFile(new File("DeleteFile.java")));
        System.out.println(deleteFile(new File("DeleteFile.java.bak")));
        System.out.println(deleteFile(new File("DeleteFile.java.bak.bak")));
        System.out.println(deleteFile(new File("DeleteFile.java.bak.bak.bak")));
        System.out.println(deleteFile(new File("DeleteFile.java.bak.bak.bak.bak")));
    }

    public static boolean deleteFile(File file) {
        if (file.exists()) {
            if (file.isFile()) {
                return file.delete();
            } else {
                File[] files = file.listFiles();
                for (File f : files) {
                    deleteFile(f);
                }
                return file.delete();
            }
        }
        return false;
    }

}

