import com.google.common.base.Preconditions;

/**
 * A {@link PatternNode} that matches a single character.
 */
public class Terminal extends PatternNode {

    /**
     * The character that will be matched.
     */
    private final char charValue;

    public Terminal(char charValue) {
        this.charValue = charValue;
    }

    public char getCharValue() {
        return charValue;
    }

    @Override
    public String toString() {
        return "Terminal[" + charValue + "]";
    }

    @Override
    protected boolean equals(Object obj) {
        if (this == obj)
            return true;
        if (!super.equals(obj))
            return false;
        if (getClass()!= obj.getClass())
            return false;
        Terminal other = (Terminal) obj;
        if (charValue!= other.charValue)
            return false;
        return true;
    }

    @Override
    protected int hashCode() {
        final int prime = 31;
        int result = super.hashCode();
        result = prime * result + charValue;
        return result;
    }

    @Override
    protected void check(PatternNode child, int childIndex) {
        Preconditions.checkArgument(child instanceof Empty, "Must be Empty");
    }
}
