import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.RecursiveTask;

public class MultiThread1 {
    private static class CountTask extends RecursiveTask<Integer> {
        private int start;
        private int end;
        private int threshold;

        public CountTask(int start, int end, int threshold) {
            this.start = start;
            this.end = end;
            this.threshold = threshold;
        }

        @Override
        protected Integer compute() {
            int sum = 0;
            if (end - start < threshold) {
                for (int i = start; i < end; i++) {
                    sum += i;
                }
            } else {
                int middle = (start + end) / 2;
                CountTask left = new CountTask(start, middle, threshold);
                CountTask right = new CountTask(middle, end, threshold);
                left.fork();
                right.fork();
                sum = left.join() + right.join();
            }
            return sum;
        }
    }

    public static int sum(int start, int end, int threshold) {
        return new ForkJoinPool().invoke(new CountTask(start, end, threshold));
    }

