import java.util.List;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import com.challenge.challenge.model.Challenge;
import com.challenge.challenge.service.ChallengeService;

@CrossOrigin("*")
@RestController
@RequestMapping("/challenge")
public class ChallengeController {

	@Autowired
	private ChallengeService challengeService;

	@GetMapping("/all")
	public ResponseEntity<List<Challenge>> getAll() {
		List<Challenge> challenges = challengeService.getAll();
		if (challenges.isEmpty()) {
			return new ResponseEntity<>(HttpStatus.NO_CONTENT);
		}
		return new ResponseEntity<>(challenges, HttpStatus.OK);
	}

	@GetMapping("/{id}")
	public ResponseEntity<Challenge> getChallenge(@PathVariable("id") Long id) {
		Challenge challenge = challengeService.getChallenge(id);
		if (challenge == null) {
			return new ResponseEntity<>(HttpStatus.NOT_FOUND);
		}
		return new ResponseEntity<>(challenge, HttpStatus.OK);
	}

}
