        try {
            while ((line = reader.readLine())!= null) {
                builder.append(line);
                builder.append("\n");
            }
        } catch (IOException e) {
            throw new SublimeException("Error reading from stdin", e);
        }

        return builder.toString().split("\n");
    }
}
