import java.util.List;

import org.jgrapht.Graph;
import org.jgrapht.Graphs;
import org.jgrapht.graph.DefaultEdge;
import org.jgrapht.graph.SimpleGraph;

import it.polito.tdp.ext2.db.Ext2DAO;

public class Model {

	private Ext2DAO dao;
	private Graph<File, DefaultEdge> grafo;

	public Model() {
		this.dao = new Ext2DAO();
		this.grafo = new SimpleGraph<>(DefaultEdge.class);
	}

	public List<File> getAllFiles() {
		return dao.getAllFiles();
	}

	public List<File> getFilesByInode(int inode) {
		return dao.getFilesByInode(inode);
	}

	public void creaGrafo() {
		List<File> files = this.getAllFiles();
		for(File f : files) {
			grafo.addVertex(f);
		}
		for(File f : files) {
			for(File f2 : dao.getFilesByInode(f.getInode())) {
				grafo.addEdge(f, f2);
			}
		}
	}

	public List<File> getSuccessors(int inode) {
		List<File> files = this.getFilesByInode(inode);
		List<File> res = new ArrayList<>();
		for(File f : files) {
			res.addAll(Graphs.successorsOf(grafo, f));
		}
		return res;
	}

	public List<File> getPredecessors(int inode) {
		List<File> files = this.getFilesByInode(inode);
		List<File> res = new ArrayList<>();
		for(File f : files) {
			res.addAll(Graphs.predecessorsOf(grafo, f));
		}
		return res;

}
