public static void main(String[] args) {
    try {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String mime_type = br.readLine();
        String command_to_execute = br.readLine();

        if (mime_type.equals("text/x-java")) {
            CommandBuilder builder = new CommandBuilder();
            String[] command_parts = command_to_execute.split(" ");
            for (int i = 0; i < command_parts.length; i++) {
                boolean contains_quote = command_parts[i].contains("\"");
                if (!contains_quote) {
                    builder.addArgument(command_parts[i]);
                } else {
                    int quote_index = command_parts[i].indexOf("\"");
                    builder.addArgument(command_parts[i].substring(0, quote_index));
                    builder.addArgument(command_parts[i].substring(quote_index + 1, command_parts[i].length()));
                }
            }
            String command = builder.getCommandNoQuotes();
            Process proc = Runtime.getRuntime().exec(command);
            proc.waitFor();
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
}
