    public String[] longestConsec(String[] strarr, int k) {
        if (k > 0 && strarr.length >= k) {
            String result = strarr[0];
            for (int i = 1; i < k; i++) {
                result += strarr[i];
            }
            String[] res = new String[2];
            res[0] = result;
            res[1] = strarr[k - 1];
            return res;
        }
        return new String[0];
    }
}
