package com.github.zeb.exercism.java.bob;

/**
 * Bob is a lackadaisical teenager. In conversation, his responses are very limited.
 * Bob answers 'Sure.' if you ask him a question.
 * He answers 'Whoa, chill out!' if you yell at him.
 * He says 'Fine. Be that way!' if you address him without actually saying
 * anything.
 * He answers 'Whatever.' to anything else.
 *
 * Bob's conversational partner is a purist when it comes to written communication and always follows
 * normal rules regarding sentence punctuation in English.
 *
 * @author 
 */
public class Bob {
    private static final String SURE = "Sure.";
    private static final String WHAT = "Whoa, chill out!";
    private static final String FINE = "Fine. Be that way!";
    private static final String WHAT_WHAT = "Whatever.";
    private static final String WHAT_WHAT_WHAT = "Whatever.";

    private static final String QUESTION = "?";
    private static final String SHAME = "!";
    private static final String SHAME_WHAT_WHAT = "!?";

    /**
     * Returns a response from Bob.
     *
     * @param statement Bob's input statement.
     * @return Bob's response.
     */
    public static String hey(String statement) {
        statement = statement.trim();

        if (statement.isEmpty()) {
            return FINE;
        }

        if (statement.endsWith(QUESTION)) {
            return SURE;
        }

        if (statement.endsWith(SHAME)) {
            return WHAT;
        }

        if (statement.endsWith(SHAME_WHAT_WHAT)) {
            return WHAT_WHAT;
        }

        if (statement.endsWith(WHAT)) {
            return WHAT_WHAT_WHAT;
        }

        return WHAT;
    }
}
