import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

import com.javapapers.java.interview.questions.thread.concurrency.ConcurrencyInterviewQuestions;
import com.javapapers.java.interview.questions.thread.concurrency.ForkJoinInterviewQuestions;

public class ThreadInterviewQuestions {

	public static void main(String[] args) throws InterruptedException, ExecutionException, TimeoutException {

		// Thread Interview Questions
		System.out.println("Thread Interview Questions");
		new ThreadInterviewQuestions().run();

		// Concurrency Interview Questions
		System.out.println("Concurrency Interview Questions");
		new ConcurrencyInterviewQuestions().run();

		// ForkJoin Interview Questions
		System.out.println("ForkJoin Interview Questions");
		new ForkJoinInterviewQuestions().run();
	}

	public void run() {
		ExecutorService executorService = Executors.newFixedThreadPool(10);
		List<Future<Integer>> futures = new ArrayList<>();
		for (int i = 0; i < 10; i++) {
			futures.add(executorService.submit(new Callable<Integer>() {
				public Integer call() throws Exception {
					Thread.sleep(1000L);
					return 10;
				}
			}));
		}
		for (Future<Integer> future : futures) {
			try {
				System.out.println("Result: " + future.get(1, TimeUnit.SECONDS));
			} catch (InterruptedException | ExecutionException | TimeoutException e) {
				e.printStackTrace();
			}
		}
		executorService.shutdown();
	}

}
