package com.github.mraof.minitalk.server;

import java.io.IOException;
import java.net.DatagramPacket;
import java.net.DatagramSocket;
import java.net.InetAddress;
import java.net.SocketException;

import com.github.mraof.minitalk.client.Client;

import static com.github.mraof.minitalk.Utilities.*;

public class Server {
    public static void main(String[] args) throws SocketException {
        DatagramSocket socket = new DatagramSocket(Integer.parseInt(args[0]));
        System.out.println("Listening on port " + socket.getLocalPort());
        try {
            byte[] data = new byte[1024];
            DatagramPacket packet = new DatagramPacket(data, data.length);
            socket.receive(packet);
            String message = new String(packet.getData(), 0, packet.getLength());
            int pid = Integer.parseInt(message);

            System.out.println("Received message from client " + pid + ": " + message);

            Client client = new Client(pid);
            client.start();

            System.out.println("Waiting for client to terminate...");
            client.join();
            System.out.println("Client terminated.");

            socket.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

}

