import nl.hu.zld.assignment2.model.Person;
import nl.hu.zld.assignment2.service.PersonService;

@Controller
public class PersonController {

	@Autowired
	private PersonService personService;

	@GetMapping("/persons")
	public String getPersons(Model model) {
		model.addAttribute("persons", personService.getAllPersons());
		return "persons";
	}

	@GetMapping("/persons/add")
	public String getAddPerson(Model model) {
		model.addAttribute("person", new Person());
		return "addPerson";
	}

	@PostMapping("/persons/add")
	public ModelAndView postAddPerson(@ModelAttribute Person person) {
		personService.addPerson(person);
		return new ModelAndView("redirect:/persons");
	}

	@GetMapping("/persons/delete")
	public String getDeletePerson(@RequestParam int id, RedirectAttributes redirectAttributes) {
		personService.deletePerson(id);
		redirectAttributes.addFlashAttribute("success", "Person was deleted.");
		return "redirect:/persons";
	}
}
