import java.util.Scanner;

public class C02_10_Find_the_next_perfect_square {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a number: ");
        int number = scanner.nextInt();
        System.out.println(number + " is the next perfect square: " + findNextPerfectSquare(number));
        scanner.close();
    }

    public static int findNextPerfectSquare(int number) {
        int squareRoot = (int) Math.sqrt(number);
        int next = squareRoot + 1;
        int nextSquare = next * next;
        return nextSquare;
    }
}

