package com.exercism.java.exercises.concept.saddlePoints;

import java.util.ArrayList;
import java.util.List;

public class SaddlePoints {
    public static List<Integer[]> getSaddlePoints(int[][] matrix) {
        List<Integer[]> result = new ArrayList<>();
        int rows = matrix.length;
        int cols = matrix[0].length;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isSaddlePoint(matrix, i, j)) {
                    result.add(new Integer[] {i, j});
                }
            }
        }
        return result;
    }

    private static boolean isSaddlePoint(int[][] matrix, int row, int col) {
        int max = matrix[row][col];
        for (int i = 0; i < matrix[row].length; i++) {
            if (matrix[row][i] > max) {
                return false;
            }
        }
        int min = matrix[row][col];
        for (int i = 0; i < matrix.length; i++) {
            if (matrix[i][col] < min) {
                return false;
            }
        }
        return true;
    }
}
