		assistant.startAssistant();
	}

	private void startAssistant() {
		Scanner scanner = new Scanner(System.in);
		System.out.println("Olá, eu sou o Assistente do Caelum e estou aqui para ajudar você.");
		System.out.println("Para sair digite'sair' ou 'exit'.");
		String input = "";
		while (true) {
			System.out.print("> ");
			input = scanner.nextLine();
			if (input.equalsIgnoreCase("sair") || input.equalsIgnoreCase("exit")) {
				break;
			}
			try {
				String result = command.execute(input);
				System.out.println(result);
			} catch (AssistantException e) {
				System.out.println(e.getMessage());
			}
		}
		scanner.close();
		System.out.println("Até mais!");
	}
