        System.out.println(solution(10));
        System.out.println(solution(11));
        System.out.println(solution(12));
        System.out.println(solution(13));
    }

    public static String solution(int n) {
        if (n < 3) {
            return "-1";
        }

        String answer = "";
        String three = "555";
        String five = "33333";

        while (true) {
            if (n % 3 == 0 && n % 5 == 0) {
                answer = getAnswer(n, three, five);
                break;
            }

            if (n < 5) {
                break;
            }

            n -= 5;
            answer += five;
        }

        if (answer.length() == 0) {
            return "-1";
        }

        return answer;
    }

    private static String getAnswer(int n, String three, String five) {
        StringBuilder answer = new StringBuilder();

        int threeCount = n / 3;
        for (int i = 0; i < threeCount; i++) {
            answer.append(three);
        }

        int fiveCount = n % 3;
        for (int i = 0; i < fiveCount; i++) {
            answer.append(five);
        }

        return answer.toString();
    }
}
