import java.util.Scanner;

public class LeftRotation {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int k = in.nextInt();
        int[] a = new int[n];
        for (int a_i = 0; a_i < n; a_i++) {
            a[a_i] = in.nextInt();
        }
        int[] b = new int[n];
        for (int i = 0; i < n; i++) {
            if (i + k < n) {
                b[i + k] = a[i];
            } else {
                b[i + k - n] = a[i];
            }
        }
        for (int i = 0; i < n; i++) {
            System.out.print(b[i] + " ");
        }
        in.close();
    }
}
