	public void solve(int testNumber, InputReader in, OutputWriter out) {
		this.in = in;
		this.out = out;

		int k = in.readInt();
		int l = in.readInt();
		int m = in.readInt();
		int n = in.readInt();
		int d = in.readInt();

		int count = 0;
		for (int i = 1; i <= d; i++) {
			if (i % k == 0 || i % l == 0 || i % m == 0 || i % n == 0) {
				count++;
			}
		}
		out.println(count);
	}
}
