        if (isYelling) {
            return "Whoa, chill out!";
        }
        if (isQuestion) {
            return "Sure.";
        }
        return "Whatever.";
    }

    private boolean isYelling(String input) {
        if (!input.matches("[A-Za-z]+")) {
            return false;
        }
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (c >= 'A' && c <= 'Z') {
                return true;
            }
            if (c >= 'a' && c <= 'z') {
                return false;
            }
        }
        return false;
    }

