package com.github.hcsp.io;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

public class FileSearch {
    // 找到给定的文件，如果存在则添加到文件列表，否则添加到目录列表
    public static List<File> findFilesByName(File root, String fileName) {
        // 这里需要实现一个功能，如果root是文件，并且是fileName，则返回root，否则返回空列表
        // 如果root是目录，则返回root目录下的所有文件中，名字是fileName的文件
        // 如果root既不是文件也不是目录，返回空列表
        // 在这里实现代码
        List<File> files = new ArrayList<>();
        if (root.isFile() && root.getName().equals(fileName)) {
            files.add(root);
        } else if (root.isDirectory()) {
            for (File file : root.listFiles()) {
                if (file.isFile() && file.getName().equals(fileName)) {
                    files.add(file);
                } else if (file.isDirectory()) {
                    files.addAll(findFilesByName(file, fileName));
                }
            }
        }
        return files;
    }

    // 打印文件列表
    public static void printFiles(List<File> files) {
        for (File file : files) {
            System.out.println(file.getAbsolutePath());
        }
    }

    // 读取用户输入的目录，查找文件，将查找到的列表打印
    public static void main(String[] args) throws IOException {
        Scanner scanner = new Scanner(System.in);
        System.out.println("请输入要查找的目录");
        String path = scanner.nextLine();
        File root = new File(path);
        System.out.println("请输入要查找的文件名");
        String fileName = scanner.nextLine();
        List<File> files = findFilesByName(root, fileName);
        printFiles(files);
    }
}
