        delayQueue.add(new Job() {
            @Override
            public void doSomething() {
                System.out.println("Hello");
            }
        }, 1000);
        // 往队列里添加一个任务，延迟2秒执行
        delayQueue.add(new Job() {
            @Override
            public void doSomething() {
                System.out.println("World");
            }
        }, 2000);
        // 等待1秒钟，查看输出结果
        Thread.sleep(1000);
        // 等待2秒钟，查看输出结果
        Thread.sleep(2000);
        // 等待3秒钟，查看输出结果
        Thread.sleep(3000);
    }

    public static class Job implements Runnable, Delayed {
        private Random random = new Random();

        @Override
        public void doSomething() {
            System.out.println(random.nextInt(1000000));
        }

        @Override
        public long getDelay(TimeUnit unit) {
            return unit.convert(1000000000, TimeUnit.NANOSECONDS);
        }

        @Override
        public int compareTo(Delayed o) {
            return 0;
        }
    }
