public class ZDT4 extends AbstractIntegerProblem {

    private static final long serialVersionUID = 1L;

    public ZDT4() {
        super(1, 2, 2);
    }

    public ZDT4(int numberOfVariables, int numberOfObjectives, int numberOfConstraints) {
        super(numberOfVariables, numberOfObjectives, numberOfConstraints);
    }

    @Override
    public void evaluate(IntegerSolution solution) {
        double x1 = (double) solution.getVariableValue(0);
        double x2 = (double) solution.getVariableValue(1);

        double g = 1 + 9 * x2;
        double h = 1 - Math.sqrt(x1 / g);
        double r = g * h;
        double s = x1 / r;

        double fm = 1.0 / (s + 1);
        double z1 = g * fm;
        double z2 = h * fm;

        solution.setObjective(0, z1);
        solution.setObjective(1, z2);
    }

    @Override
    public IntegerSolution createSolution() {
        IntegerSolution solution = new IntegerSolution(this);
        ArrayList<Double> variableValues = new ArrayList<>();
        variableValues.add(0.0);
        variableValues.add(0.0);
        solution.setVariableValues(variableValues);
        return solution;
    }
}
