        return "login";
    }

    @GetMapping("/login")
    public String loginPage() {
        return "login";
    }

    @PostMapping("/login")
    public String login(Model model, @RequestParam("username") String username, @RequestParam("password") String password, HttpSession httpSession) {
        if (username.equals("admin") && password.equals("")) {
            return "admin/index";
        } else if (username.equals("user") && password.equals("")) {
            List<Submission> submissions = new ArrayList<>();
            submissions.addAll(submissionService.findAllByUsername(username));
            httpSession.setAttribute("submissions", submissions);
            return "user/index";
        } else {
            model.addAttribute("error", "Invalid username/password!");
            return "login";
        }
    }

    @GetMapping("/logout")
    public String logout(HttpSession httpSession) {
        httpSession.invalidate();
        return "login";
    }

}
