public class FSA {
    private final Set<String> alphabet;
    private final Set<String> states;
    private final List<String> startStates;
    private final Set<String> acceptingStates;
    private final List<Transition> transitions;

    public FSA(Set<String> alphabet, Set<String> states, List<String> startStates, Set<String> acceptingStates, List<Transition> transitions) {
        this.alphabet = alphabet;
        this.states = states;
        this.startStates = startStates;
        this.acceptingStates = acceptingStates;
        this.transitions = transitions;
    }

    public Set<String> getAlphabet() {
        return alphabet;
    }

    public Set<String> getStates() {
        return states;
    }

    public List<String> getStartStates() {
        return startStates;
    }

    public Set<String> getAcceptingStates() {
        return acceptingStates;
    }

    public List<Transition> getTransitions() {
        return transitions;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass()!= o.getClass()) return false;
        FSA fsa = (FSA) o;
        return alphabet.equals(fsa.alphabet) &&
                states.equals(fsa.states) &&
                startStates.equals(fsa.startStates) &&
                acceptingStates.equals(fsa.acceptingStates) &&
                transitions.equals(fsa.transitions);
    }

    @Override
    public int hashCode() {
        return Objects.hash(alphabet, states, startStates, acceptingStates, transitions);
    }

    @Override
    public String toString() {
        return "FSA{" +
                "alphabet=" + alphabet +
                ", states=" + states +
                ", startStates=" + startStates +
                ", acceptingStates=" + acceptingStates +
                ", transitions=" + transitions +
                '}';

