class KeyWordCleaner extends FilterReader {
    private static final Set<String> KEYWORDS = Set.of("UNION");

    public KeyWordCleaner(Reader input) {
        super(input);
    }

    @Override
    public int read(char[] cbuf, int off, int len) throws IOException {
        int read = super.read(cbuf, off, len);
        if (read > 0) {
            for (int i = off; i < off + read; i++) {
                if (KEYWORDS.contains(String.valueOf(cbuf[i]))) {
                    cbuf[i] ='';
                }
            }
        }
        return read;
    }
}

