public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        List<String> lines = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            lines.add(in.next());
        }
        in.close();
        try {
            for (String line : lines) {
                System.out.println(new Solution().balanced(line));
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

class Solution {
    public String balanced(String input) {
        Stack<Character> stack = new Stack<>();
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (c == '(' || c == '[' || c == '{') {
                stack.push(c);
                continue;
            }
            if (stack.isEmpty()) {
                return "No";
            }
            char p = stack.pop();
            if (c == ')' && p!= '(') {
                return "No";
            }
            if (c == ']' && p!= '[') {
                return "No";
            }
            if (c == '}' && p!= '{') {
                return "No";
            }
        }
        return stack.isEmpty()? "Yes" : "No";
    }
}
