package org.exercism.java.exercises.primefactors;

import java.util.ArrayList;
import java.util.List;

public class PrimeFactors {

    public List<Integer> of(int input) {
        List<Integer> primeFactors = new ArrayList<>();

        while(input % 2 == 0) {
            primeFactors.add(2);
            input /= 2;
        }

        for(int i = 3; i <= Math.sqrt(input); i += 2) {
            while(input % i == 0) {
                primeFactors.add(i);
                input /= i;
            }
        }

        if(input > 2) {
            primeFactors.add(input);
        }

        return primeFactors;
    }
}
