package com.github.l33tl4b4r.triviagame.util;

import java.util.Objects;

public class InputResponsePair<T, V> {
    private T input;
    private V response;

    public InputResponsePair(T input, V response) {
        this.input = input;
        this.response = response;
    }

    public T getInput() {
        return input;
    }

    public V getResponse() {
        return response;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass()!= o.getClass()) return false;
        InputResponsePair<?,?> that = (InputResponsePair<?,?>) o;
        return input.equals(that.input) &&
                response.equals(that.response);
    }

    @Override
    public int hashCode() {
        return Objects.hash(input, response);
    }

    @Override
    public String toString() {
        return "InputResponsePair{" +
                "input=" + input +
                ", response=" + response +
                '}';
    }
}
