			if (srcDir.getAbsolutePath().equals(path)) {
				try {
					files.addAll(FileUtils.getFilesInDirectory(srcDir));
				} catch (IOException e) {
					throw new CoreException(e.getStatus());
				}
			}
		}
		return files;
	}

