public class Solution41 {
    /**
     * Erstelle ein Programm, das eine Zahl einliest und überprüft, ob es sich um eine Primzahl handelt.
     * 
     * Zum testen kannst du die Primzahlen von 1 bis 100 überprüfen.
     */
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int num = scan.nextInt();

        if (isPrime(num)) {
            System.out.printf("%d ist eine Primzahl", num);
        } else {
            System.out.printf("%d ist keine Primzahl", num);
        }
    }

    private static boolean isPrime(int num) {
        for (int i = 2; i <= (num / 2); i++) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}
