        // Write output to file
        writeFile(input, "output.txt");
    }

    /**
     * Leest een file in en zet de inhoud in een string.
     * 
     * @param fileName
     *            De naam van de file.
     * @return De inhoud van de file als string.
     */
    public static String readFile(String fileName) {
        File file = new File(fileName);
        StringBuilder text = new StringBuilder();

        try (BufferedReader br = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = br.readLine())!= null) {
                text.append(line);
                text.append('\n');
            }
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        } catch (IOException e) {
            e.printStackTrace();
        }

        return text.toString();
    }

    /**
     * Schrijft een string naar een file.
     * 
     * @param input
     *            De string die geschreven moet worden.
     * @param fileName
     *            De naam van de file.
     */
    public static void writeFile(String input, String fileName) {
        File file = new File(fileName);
        try {
            if (!file.exists()) {
                file.createNewFile();
            }
            Scanner scanner = new Scanner(file);
            scanner.close();
        } catch (IOException e) {
            e.printStackTrace();
        }

        try {
            FileWriter fw = new FileWriter(file);
            fw.write(input);
            fw.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
