package com.github.aymane_nassiri.codewars.solutions.kyu7;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;

public class WhoLikesIt {

  public static String likes(String[] names) {
    if (names.length == 0) {
      return "no one likes this";
    } else if (names.length == 1) {
      return names[0] + " likes this";
    } else if (names.length == 2) {
      return names[0] + " and " + names[1] + " like this";
    } else if (names.length == 3) {
      return names[0] + ", " + names[1] + " and " + names[2] + " like this";
    } else {
      List<String> namesList = Arrays.asList(names);
      Collections.reverse(namesList);
      return namesList.subList(0, 2).toString().replace("[", "")
         .replace("]", "")
         .replace(",", " and ")
          + " and " + names[names.length - 1] + " like this";
    }
  }

  public static void main(String[] args) {
    String[] names = {"Jacob", "Alex", "Mark", "Max", "Max", "Max", "Max"};
    System.out.println(likes(names));
  }

}
