public static String removeScriptTags(String input) {
    StringBuilder output = new StringBuilder();
    int startTagIndex = -1;
    int endTagIndex = -1;
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '<') {
            startTagIndex = i;
        } else if (c == '>') {
            endTagIndex = i;
            if (startTagIndex!= -1) {
                output.append(input.substring(startTagIndex, endTagIndex + 1));
                startTagIndex = -1;
                endTagIndex = -1;
            }
        }
    }
    return output.toString();
}
}
