import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.stream.Stream;

import main.exceptions.InputException;

public class Input {

    public static String read() throws InputException {
        try (Stream<String> stream = Files.lines(Paths.get(InputSettings.getInputPath()))) {
            return stream.reduce("", (a, b) -> a + b);
        } catch (IOException e) {
            throw new InputException();
        }
    }
}
