package it.unibo.ai.didattica.comparators;

import java.util.Comparator;

import it.unibo.ai.didattica.model.Exercise;

public class Comparators {

	public static Comparator<Exercise> byDate() {
		return new Comparator<Exercise>() {
			@Override
			public int compare(Exercise o1, Exercise o2) {
				return o1.getDate().compareTo(o2.getDate());
			}
		};
	}

	public static Comparator<Exercise> byCategory() {
		return new Comparator<Exercise>() {
			@Override
			public int compare(Exercise o1, Exercise o2) {
				return o1.getCategory().compareTo(o2.getCategory());
			}
		};
	}

	public static Comparator<Exercise> byName() {
		return new Comparator<Exercise>() {
			@Override
			public int compare(Exercise o1, Exercise o2) {
				return o1.getName().compareTo(o2.getName());
			}
		};
	}
}
