package com.github.zgs.leetcode.easy;

/**
 * @author 
 * @since 2019-07-26 22:30
 */
public class Q0434_NumberOfSegmentsInString {

    public int countSegments(String s) {
        if (s == null || s.length() == 0) {
            return 0;
        }
        int count = 0;
        int i = 0;
        int len = s.length();
        while (i < len) {
            while (i < len && s.charAt(i) =='') {
                i++;
            }
            if (i >= len) {
                break;
            }
            count++;
            while (i < len && s.charAt(i)!='') {
                i++;
            }
        }
        return count;
    }
}
