		int r, g, b;
		try {
			r = Integer.parseInt(colorString.substring(0, 2), 16);
			g = Integer.parseInt(colorString.substring(2, 4), 16);
			b = Integer.parseInt(colorString.substring(4, 6), 16);
		} catch (NumberFormatException e) {
			return null;
		}

		return new Color(r, g, b);
	}
}
