package fi.csc.web.service;

import java.util.ArrayList;
import java.util.List;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import fi.csc.web.dao.Dao;
import fi.csc.web.dao.UserDao;
import fi.csc.web.model.User;

@Service
public class Service implements ServiceInterface {

	@Autowired
	private UserDao userDao;

	public Service() { }

	public Service(UserDao userDao) {
		this.userDao = userDao;
	}

	public void setUserDao(UserDao userDao) {
		this.userDao = userDao;
	}

	// Get all users from database
	public List<User> getUsers() {
		return userDao.getUsers();
	}

	// Get user with id from database
	public User getUser(int id) {
		return userDao.getUser(id);
	}

	// Save new user to database
	public void saveUser(User user) {
		userDao.saveUser(user);
	}

	// Get user by email adress from database
	public User getUserByUsername(String username) {
		return userDao.getUserByUsername(username);
	}

	// Delete user with id from database
	public void deleteUser(int id) {
		userDao.deleteUser(id);
	}
}
