package org.tigris.programming.language.java.compiler.data;

import org.tigris.programming.language.java.compiler.JavaClassCompiler;
import org.tigris.programming.language.java.compiler.JavaFileCompiler;

import java.util.Arrays;
import java.util.List;

public class JavaClass {
    public final String name;
    public final String superClassName;
    public final String[] importClasses;
    public final List<JavaMethod> methods;

    public JavaClass(String name, String superClassName, String[] importClasses, List<JavaMethod> methods) {
        this.name = name;
        this.superClassName = superClassName;
        this.importClasses = importClasses;
        this.methods = methods;
    }

    public String compile(JavaFileCompiler compiler) {
        String java = name + " extends " + superClassName + " {\n";
        if (importClasses!= null) {
            java += Arrays.stream(importClasses).map(c -> "import " + c + ";\n").reduce("", (s1, s2) -> s1 + s2);
        }
        for (JavaMethod method : methods) {
            java += method.compile(compiler);
        }
        java += "}";
        return java;
    }

    public String compile(JavaClassCompiler compiler) {
        String java = name + " extends " + superClassName + " {\n";
        if (importClasses!= null) {
            java += Arrays.stream(importClasses).map(c -> "import " + c + ";\n").reduce("", (s1, s2) -> s1 + s2);
        }
        for (JavaMethod method : methods) {
            java += method.compile(compiler);
        }
        java += "}";
        return java;
    }
}
