package hu.bme.mit.train.rail;

import hu.bme.mit.train.interfaces.TrainController;
import hu.bme.mit.train.interfaces.TrainControllerListener;
import hu.bme.mit.train.interfaces.TrainSensor;
import hu.bme.mit.train.interfaces.TrainUser;
import hu.bme.mit.train.interfaces.TrainUserListener;
import hu.bme.mit.train.interfaces.TrainUserStrategy;

public class RailCar implements TrainSensor, TrainControllerListener {
	private TrainController trainController;
	private TrainUserListener trainUserListener;
	private TrainUserStrategy trainUserStrategy;
	private int currentPosition;

	public RailCar(TrainController trainController, TrainUserListener trainUserListener, TrainUserStrategy trainUserStrategy) {
		this.trainController = trainController;
		this.trainUserListener = trainUserListener;
		this.trainUserStrategy = trainUserStrategy;
		this.currentPosition = 0;
	}

	@Override
	public void trainControllerArrived() {
		trainUserListener.trainArrived();
		trainUserStrategy.handle(currentPosition);
		currentPosition = 0;
	}

	@Override
	public void accelerate(int speed) {
		this.currentPosition += speed;
	}

	@Override
	public void brake(int speed) {
		this.currentPosition -= speed;
	}
}
