    public static boolean verifyToken(String token) {
        try {
            // Obtem o header do token (JSON)
            Map<String, Object> header = new HashMap<>();
            String headerStr = token.split("\\.")[0];
            headerStr = new String(Base64.getUrlDecoder().decode(headerStr));
            header = new HashMap<>(new Gson().fromJson(headerStr, header.getClass()));

