            String payloadStr = token.split("\\.")[1];
            payloadStr = new String(Base64.getUrlDecoder().decode(payloadStr));
            payload = new Gson().fromJson(payloadStr, payload.getClass());

            // Verifica se o token tem assinatura
            if (header.get("alg")!= null &&!header.get("alg").equals("none")) {
                // Verifica se o token tem assinatura valida
                // Algoritmos suportados: HS256, HS512, HS384
                if (header.get("alg").equals("HS256")) {
                    // Verifica se o token tem assinatura valida
