        String expectedNotBefore, String expectedExpiresIn) {
    // 验证令牌的签名
    Map<String, String> claims = decodeToken(token);
    String receivedAlgorithm = claims.get("alg");
    if (receivedAlgorithm == null) {
        return false;
    }
    if (!receivedAlgorithm.equals(expectedAlgorithm)) {
        return false;
    }
    // 验证令牌的颁发者
    String receivedIssuer = claims.get("iss");
    if (receivedIssuer == null) {
        return false;
    }
    if (!receivedIssuer.equals(expectedIssuer)) {
        return false;
    }
    // 验证令牌的接收者
    String receivedAudience = claims.get("aud");
    if (receivedAudience == null) {
        return false;
