class Solution {
    public List<Integer> majorityElement(int[] nums) {
        List<Integer> res = new ArrayList<>();
        int times = 0;
        int candidate = 0;
        for (int num : nums) {
            if (times == 0) {
                candidate = num;
                times++;
            } else {
                times = num == candidate? times + 1 : times - 1;
            }
        }
        times = 0;
        for (int num : nums) {
            if (num == candidate) {
                times++;
            }
        }
        if (times > nums.length / 3) {
            res.add(candidate);
        }
        return res;
    }
}
