public static boolean verifyJWT(String token) {
    try {
        String[] parts = token.split("\\.");
        String header = parts[0];
        String payload = parts[1];
        String signature = parts[2];

        Map<String, String> map = new HashMap<>();
        Base64.Decoder decoder = Base64.getDecoder();
        String[] headerParts = new String(decoder.decode(header)).split("\\n");
        for (String part : headerParts) {
            String[] keyValue = part.split(":", 2);
            map.put(keyValue[0], keyValue[1]);
        }

        byte[] signatureBytes = decoder.decode(signature);
        byte[] payloadBytes = decoder.decode(payload);

        if (map.get("alg").equals("HS256")) {
            String secret = map.get("kid");
            byte[] secretBytes = decoder.decode(secret);
            byte[] signatureHash = MessageDigest.getInstance("SHA-256").digest(payloadBytes);
            byte[] signatureHashBytes = new byte[signatureHash.length + secretBytes.length];
            System.arraycopy(signatureHash, 0, signatureHashBytes, 0, signatureHash.length);
            System.arraycopy(secretBytes, 0, signatureHashBytes, signatureHash.length, secretBytes.length);
            return Arrays.equals(signatureBytes, signatureHashBytes);
        } else if (map.get("alg").equals("none")) {
            byte[] signatureHash = new byte[0];
            return Arrays.equals(signatureBytes, signatureHash);
        } else {
            return false;
        }
    } catch (Exception e) {
        return false;
    }
}
