		headerMap.put("typ", headerJson.substring(headerJson.indexOf("\"typ\":") + 7, headerJson.indexOf("\"", headerJson.indexOf("\"typ\":"))));
		headerMap.put("alg", headerJson.substring(headerJson.indexOf("\"alg\":") + 7, headerJson.indexOf("\"", headerJson.indexOf("\"alg\":"))));
