static void cifrar(String clave, String texto) {
    try {
        SecretKeySpec key = new SecretKeySpec(clave.getBytes(), clave.length() == 16? "AES" : "DES");
        Cipher cifrador = Cipher.getInstance(clave.length() == 16? "AES" : "DES");
        cifrador.init(Cipher.ENCRYPT_MODE, key);

        byte[] datosCifrados = cifrador.doFinal(texto.getBytes());
        String resultado = "";

        for (byte dato : datosCifrados) {
            resultado += dato + " ";
        }

        System.out.printf("%s", resultado);
    } catch (Exception ex) {
        System.out.printf("Error: %s", ex.getMessage());
    }
    System.out.println();
}
