package id.ac.ui.cs.mobileprogramming.fakhri.assignment1.util;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Util {

    /**
     * Mengurai header HTTP.
     * 
     * Fungsi ini memvalidasi format header menggunakan ekspresi reguler untuk memastikan
     * ia hanya mengandung karakter alfanumerik dan spasi.
     */
    public static boolean validateHeader(String header){
        String regex = "[a-zA-Z0-9 ]+";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(header);
        return matcher.matches();
    }

    /**
     * Mengurai body HTTP.
     * 
     * Fungsi ini memvalidasi format body menggunakan ekspresi reguler untuk memastikan
     * ia hanya mengandung karakter alfanumerik dan spasi.
     */
    public static boolean validateBody(String body){
        String regex = "[a-zA-Z0-9 ]+";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(body);
        return matcher.matches();
    }

    /**
     * Mengurai body HTTP.
     * 
     * Fungsi ini merubah body HTTP menjadi list string.
     */
    public static List<String> splitBody(String body){
        List<String> list = new ArrayList<String>();
        Pattern pattern = Pattern.compile("([^\n]+)");
        Matcher matcher = pattern.matcher(body);
        while(matcher.find()){
            list.add(matcher.group(0));
        }
        return list;
    }
}
