public class TheDescent {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int highest = 0;
        int current = 0;
        for (int i = 0; i < 8; i++) {
            int mountainH = in.nextInt();
            current = i;
            while (mountainH == 0 && current < 8) {
                current++;
                mountainH = in.nextInt();
            }
            if (highest < mountainH) {
                highest = mountainH;
            }
        }
        System.out.println(current);
