/**
 * Programm küsib kasutaja käest ära failinime, mille sisu tuleb laadida,
 * teeme failist ArrayList'i, mis sisaldab kõik failist võetud sisu.
 * 
 * @param args - üks parameeter: failinimi
 */
public class ClassX {
    public static void main(String[] args) {
        // Küsitakse kasutaja käest failinime.
        String fileName = System.console().readLine("Sisesta failinimi: ");

        // Läheme faili sisu paremavale muutujale.
        List<String> lines = readFile(fileName);

        // Väljastame failist võetud sisu.
        for (String line : lines) {
            System.out.println(line);
        }
    }

    /**
     * Laeb failist sisu, mille failinimi on argument funktsiooni main-s.
     * 
     * @param filename failinimi
     * @return üks ArrayList, mis sisaldab failist võetud sisu
     */
    private static List<String> readFile(String fileName) {
        List<String> lines = new ArrayList<>();

        try (BufferedReader reader = new BufferedReader(new FileReader(new File(fileName)))) {
            String line = null;
            while ((line = reader.readLine())!= null) {
                lines.add(line);
            }
        } catch (IOException e) {
            System.out.println("Viga laadimisel failist!");
        }

        return lines;
    }
}
