    for (i = 1; i <= n; i++)
    {
        scanf("%d%d", &a, &b);
        if (a < b)
        {
            int t = a;
            a = b;
            b = t;
        }
        for (j = a; j >= 1; j--)
        {
            if (a % j == 0 && b % j == 0)
            {
                gcd = j;
                break;
            }
        }
        sum = a + b;
        printf("%d %d\n", gcd, sum);
    }

