public class IOUtils {
    /**
     * 从 {@code stream} 中读取字节数为 {@code length} 的数据。
     * 
     * @param stream
     * @param length
     * @return
     * @throws IOException
     */
    public static byte[] readBytes(InputStream stream, int length) throws IOException {
        byte[] data = new byte[length];
        int readLength = stream.read(data);
        if (readLength!= length) {
            throw new IOException("read length is not equal to length");
        }
        return data;
    }
}
