			byte[] bytes = Base64.getDecoder().decode(data);

			// Ay nag-decode ang binary na data sa isang ByteArrayInputStream
			// para sa pag-deserialization at pag-pindutan ng object ng gumagamit.
			ByteArrayInputStream bais = new ByteArrayInputStream(bytes);

			// Ito ay isang ObjectInputStream.
			// Lagyan ng sabihin na mayroon tayo ng pag-deserialization sa isang InputStream.
			// Sa halip, gagamitin ang ByteArrayInputStream na ito.
			ObjectInputStream ois = new ObjectInputStream(bais);

			// Ito ay isang Object.
			Object object = ois.readObject();

			// Itong nag-decode ang object sa pamamagitan ng pag-cast na sa class na
			// yun ang magsasagawa ng pag-check.
			ClassX classX = (ClassX) object;

			// Ito ay isang string.
			return classX.name;
