import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

import { User } from '../../models/user';
import { UserList } from '../../models/user_list';
import { UserWithQuestion, UserWithQuestionList } from '../../models/user_with_question';

@Injectable({
    providedIn: 'root'
})
export class UserManagementService {

    constructor(private http: HttpClient) { }

    getUserList(): Observable<UserList> {
        return this.http.get<UserList>('/api/user/list');
    }

    addUser(user: User): Observable<User> {
        return this.http.post<User>('/api/user/add', user);
    }

    deleteUser(userId: number): Observable<User> {
        return this.http.delete<User>(`/api/user/delete/${userId}`);
    }

    getUserWithQuestionList(): Observable<UserWithQuestionList> {
        return this.http.get<UserWithQuestionList>('/api/user/list/withQuestion');
    }

    getAnswerList(userId: number): Observable<UserWithQuestionList> {
        return this.http.get<UserWithQuestionList>(`/api/user/list/withQuestion/${userId}`);
    }

    deleteAnswer(userId: number, questionId: number): Observable<UserWithQuestionList> {
        return this.http.delete<UserWithQuestionList>(`/api/user/list/withQuestion/${userId}/${questionId}`);
    }
}
