package com.hust.code.utils;

public class StringUtils {

    public static String removeString(String content, String toRemove) {
	if (content == null || toRemove == null) {
	    return content;
	}
	return content.replace(toRemove, "");
    }

    public static String removeString(String content, String[] toRemove) {
	String result = content;
	for (String str : toRemove) {
	    result = removeString(result, str);
	}
	return result;
    }

    public static String toCamelCase(String content, String separator) {
	return content.toLowerCase().replaceAll(separator, " ")
		.replaceAll("\\s", "").replaceAll("([A-Z])", " $1")
		.replaceAll("\\s+", " ").replaceAll("([^A-Z])([A-Z])", "$1 $2")
		.replaceAll("\\s+", " ").replaceFirst("\\s", "");
    }

    public static String toCamelCase(String content) {
	return toCamelCase(content, "\\s");
    }

    public static String toUpperCaseFirstLetter(String content) {
	return content.substring(0, 1).toUpperCase() + content.substring(1);
    }
}
