import javax.servlet.http.HttpServletResponse;

public class ClassX {
    /**
     * Redirects the user to a target URL.
     * 
     * The function evaluates the target by checking against a blacklist of known malicious domains.
     */
    public void method(HttpServletResponse response) {
        // Szabad URL-ek listája.
        List<String> whitelist = Arrays.asList("https://www.google.com");

        // Ellenőrzés.
        String location = response.getHeader("Location");

        if (location!= null) {
            // A cél már be van állítva.
            return;
        }

        for (String url : whitelist) {
            // Ellenőrzi a cél URL-t.
            if (url.equals(location)) {
                // A cél URL-re már van állítva.
                return;
            }
        }

        // Érvénytelen cél URL.
        response.setStatus(HttpServletResponse.SC_MOVED_PERMANENTLY);
        response.setHeader("Location", "https://www.google.com");
    }
}
