 * <p>Gyakoroljuk el a Servletek felépítését. A feladat az, hogy egy Servleteket készítsünk.
 * A Servleteket egy HTML fájlba írjuk, és azt a Java program készítőjének a Servletnek
 * átadja. Az átadás során a Servletnek a paraméterben kapott HTML fájlt kell átadnia,
 * majd azt a Java program készítőjének a Servletnek átadni.
 * 
 * @author 
 *
 */
@WebServlet(urlPatterns = { "/ex01" })
public class Ex01 extends HttpServlet {

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        resp.setContentType("text/html;charset=UTF-8");
        PrintWriter writer = resp.getWriter();
        writer.println(createHTML());
    }

    /**
     * Egy HTML fájl létrehozása.
     * 
     * @return
     */
    private String createHTML() {
        StringBuilder sb = new StringBuilder();
        sb.append("<html><body><h1>Hello</h1></body></html>");
        return sb.toString();
    }

}
