     * Redireciona o usuário para uma URL de destino.
     * 
     * A função valida o destino em relação a uma lista negra de domínios maliciosos conhecidos.
     */
    public void redirecionar(String destino, HttpServletResponse response) throws Exception {
        Codec codec = ESAPI.encoder();
        if (destino!= null &&!destino.isEmpty()) {
            if (!destino.startsWith("http")) {
                destino = "http://" + destino;
            }
            String listaNegra[] = {"malicious.com", "malicious2.com"};
            boolean isMalicious = false;
            for (String dominio : listaNegra) {
                if (destino.contains(dominio)) {
                    isMalicious = true;
                    break;
                }
            }
            if (!isMalicious) {
                response.sendRedirect(codec.encodeForJavaScript(destino));
            }
        }
    }
