package com.interview.code.questions.arrays;

public class ArrayRotate {

	public static void main(String[] args) {
		int arr[] = {1,2,3,4,5,6,7,8,9};
		int n = arr.length;
		int k = 3;
		rotate(arr, n, k);
	}

	public static void rotate(int arr[], int n, int k) {
		int temp[] = new int[k];
		for(int i=0; i<k; i++) {
			temp[i] = arr[n-k+i];
		}
		for(int i=n-k; i<n; i++) {
			arr[i] = arr[i-k];
		}
		for(int i=0; i<k; i++) {
			arr[i] = temp[i];
		}
		for(int num : arr) {
			System.out.print(num + " ");
		}
	}
}
