package org.javamaster.javamaster.model;

import java.util.List;
import java.util.Objects;

public class Question extends UserGeneratedContent {

	private String title;

	private String description;

	private List<Answer> answers;

	public Question() {
	}

	public Question(String title, String description) {
		this.title = title;
		this.description = description;
	}

	public Question(String title, String description, List<Answer> answers) {
		this.title = title;
		this.description = description;
		this.answers = answers;
	}

	public String getTitle() {
		return title;
	}

	public void setTitle(String title) {
		this.title = title;
	}

	public String getDescription() {
		return description;
	}

	public void setDescription(String description) {
		this.description = description;
	}

	public List<Answer> getAnswers() {
		return answers;
	}

	public void setAnswers(List<Answer> answers) {
		this.answers = answers;
	}

	@Override
	public boolean equals(Object o) {
		if (this == o)
			return true;
		if (!(o instanceof Question))
			return false;
		Question question = (Question) o;
		return Objects.equals(getTitle(), question.getTitle()) && Objects.equals(getDescription(), question.getDescription())
				&& Objects.equals(getAnswers(), question.getAnswers());
	}

	@Override
	public int hashCode() {
		return Objects.hash(getTitle(), getDescription(), getAnswers());
	}

	@Override
	public String toString() {
		return "Question [title=" + title + ", description=" + description + ", answers=" + answers + "]";
	}
}
