package gr.uoa.di.madgik.exodus.dom;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;

import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;

import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;
import org.xml.sax.SAXException;

public class ClassX {

    /**
     * Αναλύει ένα έγγραφο XML.
     * 
     * Η συνάρτηση ελέγχει την παρουσία δηλώσεων 'DOCTYPE' για να αποτρέψει το XXE.
     */
    public static String parseXml(String xml) {
        try {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            DocumentBuilder db = dbf.newDocumentBuilder();
            InputStream is = new ByteArrayInputStream(xml.getBytes());
            Document doc = db.parse(is);
            Element root = doc.getDocumentElement();
            NodeList children = root.getChildNodes();
            for (int i = 0; i < children.getLength(); i++) {
                Node currentNode = children.item(i);
                if (currentNode.getNodeType() == Node.TEXT_NODE) {
                    if (currentNode.getNodeValue().contains("<")) {
                        return "XXE found!";
                    }
                }
            }
            return "No XXE!";
        } catch (ParserConfigurationException e) {
            return "ParserConfigurationException";
        } catch (SAXException e) {
            return "SAXException";
        } catch (IOException e) {
            return "IOException";
        }
    }
}
