    /**
     * <|info|>
     *
     * <|title|>
     * The Happy Fun Day
     *
     * <|description|>
     * Write a function that accepts a date, and returns whether it's a
     * "happy" day or not.
     *
     * A happy day is one where you get the following results:
     *
     * sum(digits(date)) == date
     * sum(digits(date)) == sum(digits(sum(digits(date))))
     *
     * digits(n) returns a list of the digits of n.
     *
     * sum(digits(n)) is the sum of the digits of n.
     *
     * sum(digits(n)) == n when n < 10
     *
     * <|example|>
     *
     * happyFunDay(2015) => false
     * happyFunDay(2017) => true
     *
     * <|end|>
     */
    public static boolean happyFunDay(int input) {
        int sum = digits(input).stream().mapToInt(Integer::intValue).sum();

        if (sum == input) {
            return true;
        }

        return sum == digits(sum).stream().mapToInt(Integer::intValue).sum();
    }

    private static List<Integer> digits(int input) {
        if (input < 10) {
            return List.of(input);
        }

        List<Integer> digits = new ArrayList<>();
        while (input > 0) {
            digits.add(input % 10);
            input /= 10;
        }

        return digits;
    }
