public class JexxCourse {
	private static final Random random = new Random();

	private final List<Exercise> exerciseList;

	public JexxCourse(JexxCourseData data) {
		exerciseList = new ArrayList<>();
		for (Problem problem : data.getProblems()) {
			exerciseList.add(new Exercise(problem));
		}
	}

	public Exercise getExercise(int index) {
		return exerciseList.get(index);
	}

	public Exercise getRandomExercise() {
		return exerciseList.get(random.nextInt(exerciseList.size()));
	}

