package com.github.securing.notary;

import java.util.HashMap;
import java.util.Map;

import com.github.securing.notary.model.Command;
import com.github.securing.notary.model.Reply;
import com.github.securing.notary.model.Server;

public class Notary {
    private final Map<String, Server> serverMap = new HashMap<>();
    private final Server server;

    public Notary(Server server) {
        this.server = server;
    }

    public Reply getReply(Command command) {
        final var reply = new Reply();
        serverMap.computeIfAbsent(command.getFrom(), key -> new Server(command.getFrom()));
        serverMap.computeIfAbsent(command.getTo(), key -> new Server(command.getTo()));
        final var serverFrom = serverMap.get(command.getFrom());
        final var serverTo = serverMap.get(command.getTo());
        if (serverFrom.isTrusted() && serverTo.isTrusted()) {
            serverFrom.addReply(serverTo, command.getRequest());
            reply.setResponse(serverTo.getResponse());
        } else {
            reply.setResponse("This server is not trusted.");
        }
        return reply;
    }

    public static void main(String[] args) {
        final var server = new Server("server");
        final var notary = new Notary(server);
        final var command = new Command("server", "client", "request");
        final var reply = notary.getReply(command);
        System.out.println(reply.getResponse());
    }
}
