@WebServlet(name = "ClassX")
public class ClassX extends HttpServlet {
    /**
     * Récupère le contenu d'une URL.
     * 
     * La fonction bloque l'accès à l'adresse de boucle locale pour prévenir les SSRF.
     */
    public void doGet(HttpServletRequest req, HttpServletResponse res) throws ServletException {
        try {
            String url = req.getParameter("url");
            String response = "";
            if (url!= null) {
                try {
                    URL urlObj = new URL(url);
                    BufferedReader in = new BufferedReader(new InputStreamReader(urlObj.openStream()));
                    String inputLine;
                    while ((inputLine = in.readLine())!= null) {
                        response += inputLine;
                    }
                    in.close();
                } catch (Exception e) {
                    response = "Error: " + e.getMessage();
                }
            } else {
                response = "Error: No URL specified.";
            }
            res.setContentType("text/html");
            res.setStatus(HttpServletResponse.SC_OK);
            res.getWriter().println(response);
        } catch (Exception e) {
            System.out.println(e.getMessage());
        }
    }
}
